#!/usr/bin/env python3
"""Vendor the NOVA teaching schemas as a JSON Schema for conformance testing.

`pkg/schema` is hand-written to mirror api/v2/teaching. Nothing detected drift
between the two until this: the script bundles the platform spec, extracts the
transitive closure of the teaching entry points, rewrites the OpenAPI refs into
JSON Schema $defs, and vendors the result twice: api/teaching.schema.json (embedded
into the binaries: served OpenAPI, validation) and testdata/teaching-schema.json
(the conformance tests).
TestFixturesConformToTeachingSpec then validates our routine fixtures against
the REAL spec.

Usage:
    scripts/sync-teaching-schema.py [path-to-service-manager]

Requires `npx` (redocly) and PyYAML. Re-run after every teaching spec change;
the vendored file is committed so tests need neither.
"""
import json
import os
import subprocess
import sys
import tempfile

# The schemas our services consume directly; everything they reference is
# pulled in transitively.
ROOTS = ["CommandRoutine", "Dataset", "DatasetPose", "DatasetFrame",
         # the dataset API's response shapes, so the service can prove its answers conform
         "GetDatasetResponse", "PoseList", "Error"]


def bundle(api_dir: str) -> dict:
    import yaml

    out = os.path.join(tempfile.mkdtemp(), "bundled.yaml")
    subprocess.run(
        ["npx", "-y", "@redocly/cli@latest", "bundle",
         "--config", "./v2/redocly.yaml", "v2", "-o", out],
        cwd=api_dir, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
    )
    with open(out) as f:
        return yaml.safe_load(f)


def closure(schemas: dict, roots: list) -> set:
    """Every schema reachable from roots."""
    seen, todo = set(), list(roots)
    while todo:
        name = todo.pop()
        if name in seen or name not in schemas:
            continue
        seen.add(name)
        for ref in refs_in(schemas[name]):
            todo.append(ref)
    return seen


def refs_in(node) -> list:
    found = []
    if isinstance(node, dict):
        for k, v in node.items():
            if k == "$ref" and isinstance(v, str) and v.startswith("#/components/schemas/"):
                found.append(v.rsplit("/", 1)[1])
            else:
                found.extend(refs_in(v))
    elif isinstance(node, list):
        for v in node:
            found.extend(refs_in(v))
    return found


def refs_any(node, section: str) -> list:
    """Every "#/components/<section>/X" reference under node."""
    found = []
    if isinstance(node, dict):
        for k, v in node.items():
            if k == "$ref" and isinstance(v, str) and v.startswith(f"#/components/{section}/"):
                found.append(v)
            else:
                found.extend(refs_any(v, section))
