def rewrite(node):
    """OpenAPI component refs -> JSON Schema $defs refs; drop OpenAPI-isms
    that JSON Schema validators reject or misread."""
    if isinstance(node, dict):
        out = {}
        for k, v in node.items():
            if k == "$ref" and isinstance(v, str) and v.startswith("#/components/schemas/"):
                out[k] = "#/$defs/" + v.rsplit("/", 1)[1]
            elif k in ("discriminator", "xml", "externalDocs", "example"):
                continue  # OpenAPI-only keywords
            elif k.startswith("x-"):
                continue  # vendor extensions
            else:
                out[k] = rewrite(v)
        return out
    if isinstance(node, list):
        return [rewrite(v) for v in node]
    return node


