// Conformance: our hand-written Go types vs the REAL NOVA teaching spec.
//
// pkg/schema mirrors api/v2/teaching by hand. Until this test nothing
// verified the mirror: a field added upstream, a renamed enum, or a shape we
// decode too loosely would go unnoticed until a customer routine behaved
// differently than the spec promises.
//
// testdata/routine-dialect-schema.json is the routine format the resolver's
// CommandRoutine routes speak, frozen from the teaching-spec draft it was
// built against (see api.RoutineDialectSchema).

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

const (
	schemaPath   = "../../testdata/routine-dialect-schema.json" // the resolver's routine format, see api.RoutineDialectSchema
	routinesGlob = "../../testdata/routines/*.json"
)

func loadTeachingSchema(t *testing.T, def string) *jsonschema.Schema {
	t.Helper()
	f, err := os.Open(schemaPath)
	if err != nil {
		t.Fatalf("vendored teaching schema missing (run `make spec-sync`): %v", err)
	}
	defer func() { _ = f.Close() }()
	doc, err := jsonschema.UnmarshalJSON(f)
	if err != nil {
		t.Fatalf("teaching schema is not valid JSON: %v", err)
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("teaching.json", doc); err != nil {
		t.Fatalf("add resource: %v", err)
	}
	s, err := c.Compile("teaching.json#/$defs/" + def)
	if err != nil {
		t.Fatalf("compile %s: %v", def, err)
	}
	return s
}

func routineFiles(t *testing.T) []string {
	t.Helper()
	files, err := filepath.Glob(routinesGlob)
	if err != nil || len(files) == 0 {
		t.Fatalf("no routine fixtures found at %s (err %v)", routinesGlob, err)
	}
	sort.Strings(files)
	return files
}

// TestFixturesConformToTeachingSpec: every routine fixture we test against
// must be a document the platform spec actually permits. A fixture that
// drifts from the spec would make every test built on it prove nothing.
func TestFixturesConformToTeachingSpec(t *testing.T) {
	sch := loadTeachingSchema(t, "CommandRoutine")
	for _, path := range routineFiles(t) {
		t.Run(filepath.Base(path), func(t *testing.T) {
			f, err := os.Open(path)
			if err != nil {
				t.Fatal(err)
			}
			defer func() { _ = f.Close() }()
			doc, err := jsonschema.UnmarshalJSON(f)
			if err != nil {
				t.Fatalf("invalid JSON: %v", err)
			}
			if err := sch.Validate(doc); err != nil {
				t.Errorf("fixture does not conform to the teaching CommandRoutine schema:\n%v", err)
			}
		})
	}
}

