// TestSpecsGenerated is the drift guarantee: the committed spec files must
// be byte-identical to what the current code generates (`make spec` fixes).
func TestSpecsGenerated(t *testing.T) {
	oa, err := generateOpenAPI()
	if err != nil {
		t.Fatalf("generate openapi: %v", err)
	}
	if disk := readFile(t, "../../api/openapi.yaml"); disk != string(oa) {
		t.Error("api/openapi.yaml is stale — run `make spec`")
	}
	aa, err := generateAsyncAPI()
	if err != nil {
		t.Fatalf("generate asyncapi: %v", err)
	}
	if disk := readFile(t, "../../api/asyncapi.yaml"); disk != string(aa) {
		t.Error("api/asyncapi.yaml is stale — run `make spec`")
	}
}

// TestSpecConsistency spot-checks the generated documents: every session
// operation and route present, in both documents, and dispatched by the
