// A ConfiguredMotionRoutine is a routine whose every cartesian target is an
// anchored pose: a pose that names the frame it is expressed in, the tool it
// was taught with, and the arm configuration that reaches it. It is the wire
// format for motion-authoring clients that hold poses rather than documents —
// a flow node, a script, a teaching UI.
//
// The names are references, not values: the frame is resolved against the
// cell's (or a dataset's) frame graph and the tool against the motion group's
// live description, here, at plan time. The planner downstream receives plain
// values and stays stateless.
//
// Conversion, not a second engine: the payload is mapped onto the routine
// document this service already plans, verifies and executes, and handed to
// the same handler. The mapping is mechanical, and everything past it —
// resolution, planning, verification, execution, supervision — is the code
// path the existing route uses, so the two cannot drift apart in behaviour.
//
// What the mapping refuses, it refuses by name. An anchored pose exists to
// remove the guesswork from a stored pose, so this decoder never supplies a
// frame, a tool, or a configuration the caller did not state.

// cmrRoutine is the posted document.
type cmrRoutine struct {
	Name        string `json:"name,omitempty"`
	MotionGroup string `json:"motion_group,omitempty"`
	// Start, DefaultMotionSettings and Metadata are the routine-level fields
	// the internal document already defines; they are carried verbatim so
	// this decoder does not become a second definition of them.
	Start                 json.RawMessage   `json:"start,omitempty"`
	DefaultMotionSettings json.RawMessage   `json:"default_motion_settings,omitempty"`
	Metadata              map[string]string `json:"metadata,omitempty"`
	Steps                 []cmrStep         `json:"steps"`
}

// cmrStep is one step of a routine: a move to an anchored pose, a move in
// joints, a timed wait, a wait or pause on I/O, or I/O written out.
type cmrStep struct {
	Type string `json:"type"`
	Name string `json:"name,omitempty"`

	// move — to a Point stated here, or to a PointRef: an AnchoredPose
	// stored in a dataset, read when the routine is planned, so re-teaching it
	// there moves every routine that names it.
	Point    *cmrPoint       `json:"point,omitempty"`
	PointRef *cmrPointRef    `json:"point_ref,omitempty"`
	Path     json.RawMessage `json:"path,omitempty"`
