"""What a resolved routine asks of a run, in the order it runs.

The motion commands form one trajectory: location ``k`` is where motion ``k`` starts and
location ``n`` (the number of motions) is its end. Every other command sits at a *boundary*
between two motions, at its place in the sequence: boundary ``k`` holds the commands
between motion ``k - 1`` and motion ``k``.

A command with an ``at`` trigger (ADR 017, spec §8) is no step at a boundary: it belongs to the path
of its nearest preceding motion (``Triggered``); where exactly is only known once the routine is
planned (``routines.plan.compile_plan``). Without a preceding motion the trigger collapses to the start and
the command runs at its place (spec §8.2). A ``pause_on_io`` sits at its boundary like any other step; where
the robot stands and what a ``pause_on_io`` does there is decided by the plan (``routines.plan``).

``lay_out`` also decides, before NOVA is asked anything, whether the service can run the
routine at all; see ``NotImplementedYet`` for what it cannot run yet.
"""

from __future__ import annotations

import contextlib
from collections.abc import Generator, Sequence
from dataclasses import dataclass
from typing import Any

from nova import api

from routines.api import models
from routines.errors import InvalidRoutine, NotImplementedYet, Rejected
from routines.io_conditions import ios_of
from routines.resolved import check_resolved
from routines.triggers import trigger_location

MotionCommand = models.ExplicitPathMotionCommand | models.GeneratedPathMotionCommand
StepCommand = (
    models.SetIOCommand
    | models.WaitForIOCommand
    | models.WaitForTimeCommand
    | models.MarkerCommand
    | models.PauseOnIOCommand
)
_HOLDING = (models.WaitForIOCommand, models.WaitForTimeCommand)


@dataclass(frozen=True)
class Step:
    """A command that is not a motion, with its index in the routine's ``commands``."""

    index: int
    command: StepCommand


@dataclass(frozen=True)
class Triggered:
    """A command with an ``at`` trigger: it belongs to the path of motion ``anchor`` (0-based)."""

    index: int
    command: StepCommand
    anchor: int

    def location(
        self, trajectory: api.models.JointTrajectory, tcp_positions: Sequence[Sequence[float]] | None
    ) -> float:
        assert self.command.at is not None
        return trigger_location(
            self.command.at.root, self.anchor, trajectory.times, trajectory.locations, tcp_positions
        )


@dataclass(frozen=True)
class PathMotion:
    """A motion planned along its path together with its neighbours (``planTrajectory``)."""

    command: api.models.MotionCommand


@dataclass(frozen=True)
class GeneratedMotion:
    """A motion whose collision-free path the planner generates (``planCollisionFree``), planned on its own."""

    target: list[float] | api.models.Pose
    """Joints, or a pose that is turned into joints by inverse kinematics."""
    algorithm: Any
    constraint: api.models.DirectionConstraint | None
    limits_override: api.models.LimitsOverride | None


Motion = PathMotion | GeneratedMotion


@dataclass(frozen=True)
class Movement:
    """A motion command, with its index in the routine's ``commands`` and how it is planned."""

    index: int
    motion: Motion


@dataclass(frozen=True)
class CommandRoutineLayout:
    routine: models.CommandRoutine
    movements: tuple[Movement, ...]
    boundaries: tuple[tuple[Step, ...], ...]
    """``boundaries[k]``: the steps between motion ``k - 1`` and motion ``k``; one more than motions."""
    triggered: tuple[Triggered, ...] = ()
    tcp: str | None = None
    """The one TCP the routine moves: the one its poses were taught with, else the routine's ``tcp``."""
    controller: str | None = None
    """The controller the request names; the only source of the controller, never derived from a motion group."""
    motion_group_override: str | None = None
    """The motion group of ``controller`` the request moves instead of the routine's; planned with its own setup."""

    @property
    def io_only(self) -> bool:
        return not self.movements

    @property
    def end(self) -> int:
        """The location of the end of the trajectory: the number of motions."""
        return len(self.movements)

    @property
    def motion_group(self) -> str:
        """The motion group the routine moves: ``motion_group_override`` if given, else the routine's."""
        if self.motion_group_override is not None:
            return self.motion_group_override
        assert self.routine.motion_group is not None, "only a motion routine has a motion group"
        return self.routine.motion_group.id

    @property
    def motion_controller(self) -> str:
        """The controller of the motion group a motion routine moves (``lay_out`` made sure it is given)."""
        assert self.controller is not None, "a motion routine is laid out with a controller"
        return self.controller

    def holds_at(self, boundary: int) -> bool:
        """Whether the robot stands still at ``boundary`` while the service runs its steps in order.

        It does before the first and after the last motion, and wherever a step waits. At every
        other boundary the robot moves on, and the controller writes the outputs on the way.
        """
        if boundary in (0, self.end):
            return True
        return any(isinstance(step.command, _HOLDING) for step in self.boundaries[boundary])

    def pieces(self) -> list[list[Movement]]:
        """The motions planned in one request each.

        Consecutive explicit-path motions are planned together, so they blend into each other; every
        generated motion on its own. A boundary where the robot holds (a wait) ends a piece
        too (ADR 003/026): the robot stops at the taught target of the motion before it.
        """
        pieces: list[list[Movement]] = []
        for k, movement in enumerate(self.movements):
            joins = (
                isinstance(movement.motion, PathMotion)
                and pieces
                and isinstance(pieces[-1][-1].motion, PathMotion)
                and not self.holds_at(k)
            )
            if joins:
                pieces[-1].append(movement)
            else:
                pieces.append([movement])
        return pieces

    @property
    def warnings(self) -> list[str]:
        """What the routine asks for but does not get: blending of a motion where the robot has to stop.

        A piece is planned on its own, so its last motion cannot blend into the next one: the robot stops
        at its target and its blending, set on the motion or inherited from the routine's defaults, is
        ignored. The routine's last motion has nothing to blend into anyway.
        """
        warnings = []
        pieces = self.pieces()
        for i in range(len(pieces) - 1):
            reason = self._stop_reason(i)
            if reason is not None:
                last = pieces[i][-1]
                warnings.append(
                    f"Command {last.index} (motion_command): its blending is ignored, the robot stops at its "
                    f"target because {reason}"
                )
        return warnings

    def _stop_reason(self, piece: int) -> str | None:
        """Why the robot stops after ``piece`` although its last motion blends; ``None`` if it does not blend."""
        pieces = self.pieces()
        last, following = pieces[piece][-1], pieces[piece + 1][0]
        if _blending_of(last.motion) is None:
            return None
        boundary = self.movements.index(following)
        holding = [step for step in self.boundaries[boundary] if isinstance(step.command, _HOLDING)]
        if holding:
            return f"command {holding[0].index} ({holding[0].command.type}) waits there"
        return f"command {following.index} (motion_command) with a generated path is planned on its own"

    @property
    def needs_tcp_positions(self) -> bool:
        """Whether a trigger is a distance along the TCP path, which needs the TCP position of every sample."""
        return any(
            item.command.at is not None and isinstance(item.command.at.root, models.DistanceTrigger)
            for item in self.triggered
        )


def lay_out(
    routine: models.CommandRoutine, controller: str | None = None, motion_group_override: str | None = None
) -> CommandRoutineLayout:
    """Check that the service can run ``routine`` on ``controller`` and lay out its commands.

    A motion routine moves ``motion_group_override``, if given, else its own motion group; both are motion groups
    of ``controller``. An I/O-only routine addresses the ``CONTROLLER`` IOs of ``controller`` and ignores
    ``motion_group_override``.

    Raises:
        InvalidRoutine: The routine is not resolved or lacks its context.
        NotImplementedYet: The routine uses a feature the service does not implement yet.
        Both are raised before NOVA is asked anything.
    """
    check_resolved(routine)
    io_only = routine.motion_group_setup is None
    if not io_only:
        _check_context(routine, controller)
    else:
        _check_io_only_context(routine)
        motion_group_override = None
    tcp = None if io_only else _tcp(routine)

    movements: list[Movement] = []
    boundaries: list[list[Step]] = [[]]
    triggered: list[Triggered] = []
    for index, wrapped in enumerate(routine.commands):
        command = wrapped.root
        label = f"Command {index} ({command.type})"
        if isinstance(command, (models.ExplicitPathMotionCommand, models.GeneratedPathMotionCommand)):
            if io_only:
                raise InvalidRoutine(
                    f"{label}: an I/O-only routine, without a motion group setup, cannot move", command_index=index
                )
            with _about(index):
                movements.append(Movement(index, _motion(routine, label, command)))
            boundaries.append([])
            continue
        if io_only and controller is None:
            with _about(index):
                _check_io_only_origin(label, command)
        if command.at is not None and movements:
            triggered.append(Triggered(index, command, anchor=len(movements) - 1))
        else:
            # Without a preceding motion (also in an I/O-only routine) an `at` trigger has no motion to anchor to:
            # it collapses to the start (spec §8.2), and the command runs at its place in the sequence.
            boundaries[-1].append(Step(index, command))

    if not io_only and not movements:
        raise InvalidRoutine("A routine with a motion group setup needs at least one motion command")
    return CommandRoutineLayout(
        routine=routine,
        movements=tuple(movements),
        boundaries=tuple(tuple(steps) for steps in boundaries),
        triggered=tuple(triggered),
        tcp=tcp,
        controller=controller,
        motion_group_override=motion_group_override,
    )


def _blending_of(motion: Motion) -> api.models.BlendingAuto | api.models.BlendingPosition | None:
    if isinstance(motion, PathMotion):
        return motion.command.blending
    return None


def unblended(command: api.models.MotionCommand) -> api.models.MotionCommand:
    """``command`` without blending: the last motion of a piece stops at its target."""
    return command.model_copy(update={"blending": None})


def _check_context(routine: models.CommandRoutine, controller: str | None) -> None:
    """A motion routine runs with its own context on the controller the request names."""
    for field in ("motion_group", "start_joint_position"):
        if getattr(routine, field) is None:
            raise InvalidRoutine(f"Routine '{routine.command_routine.root}' has no {field}")
    if controller is None:
        raise InvalidRoutine(
            f"Routine '{routine.command_routine.root}' moves a robot; pass the controller of its motion group "
            "as the request's 'controller'"
        )


def _tcp(routine: models.CommandRoutine) -> str | None:
    """The one TCP of the routine: its anchored poses' TCP is the ground truth.

    The routine's ``tcp`` is optional; where given, it must name that TCP too. A routine with poses
    taught with different TCPs would need them re-expressed for one TCP, which is not implemented yet.
    """
    tcp, source = routine.tcp, "the routine's tcp"
    for index, wrapped in enumerate(routine.commands):
        command = wrapped.root
        for name, pose in _poses(command):
            if tcp is None:
                tcp, source = pose.tcp, f"command {index}"
            elif pose.tcp != tcp:
                raise NotImplementedYet(
                    f"Command {index} ({command.type}): the {name} was taught with the TCP '{pose.tcp}', "
                    f"but {source} names the TCP '{tcp}'; a routine with more than one TCP is not implemented yet",
                    command_index=index,
                )
    return tcp


@contextlib.contextmanager
def _about(index: int) -> Generator[None]:
    """A refusal raised within is about the routine's command ``index``."""
    try:
        yield
    except Rejected as error:
        error.command_index = index
        raise


def _poses(command: Any) -> list[tuple[str, models.InlinePose]]:
    """The anchored poses a motion command moves to or through (``check_resolved`` left only inline poses)."""
    if not isinstance(command, (models.ExplicitPathMotionCommand, models.GeneratedPathMotionCommand)):
        return []
    poses = [("target", command.target.root)]
    if isinstance(command, models.ExplicitPathMotionCommand):
        via = getattr(command.path_type.root, "via_pose", None)
        if via is not None:
            poses.append(("via pose", via.root))
    return [(name, pose) for name, pose in poses if isinstance(pose, models.InlinePose)]


def _check_io_only_context(routine: models.CommandRoutine) -> None:
    """An I/O-only routine belongs to no robot: the schema forbids its motion group, TCP and start joints."""
    for field in ("motion_group", "tcp", "start_joint_position"):
        if getattr(routine, field) is not None:
            raise InvalidRoutine(
                f"Routine '{routine.command_routine.root}' is I/O-only (its motion_group_setup is null) "
                f"and must not have a {field}"
            )


def io_origins(command: StepCommand) -> list[str]:
    """The origins (``CONTROLLER``, ``BUS_IO``) of the inputs and outputs ``command`` reads or writes."""
    if isinstance(command, models.SetIOCommand):
        return [command.io_origin.root]
    if isinstance(command, (models.WaitForIOCommand, models.PauseOnIOCommand)):
        return [origin for origin, _ in ios_of(command.condition)]
    return []


def _check_io_only_origin(label: str, command: StepCommand) -> None:
    """Without a controller to run on, an I/O-only routine can only address bus IOs."""
    if "CONTROLLER" in io_origins(command):
        raise InvalidRoutine(
            f"{label}: an I/O-only routine names no controller, so it can only use BUS_IO inputs and outputs, "
            "not CONTROLLER ones; pass the controller to use as the request's 'controller'"
        )


def _motion(routine: models.CommandRoutine, label: str, command: MotionCommand) -> Motion:
    """How a routine's motion command is planned."""
    blending, limits = _settings(routine.default_motion_settings, command.motion_settings)
    if isinstance(command, models.GeneratedPathMotionCommand):
        if blending is not None:
            # spec §7.4: the collision-free planner takes no blending, so it must resolve to none.
            raise InvalidRoutine(
                f"{label}: a motion with a generated path cannot blend; set its motion_settings.blending "
                "to null to suppress the routine's default blending"
            )
        return _generated(command, limits)
    return PathMotion(api.models.MotionCommand(path=_path(label, command), blending=blending, limits_override=limits))


def _path(label: str, command: models.ExplicitPathMotionCommand) -> Any:
    path_type = command.path_type.root
    target = command.target.root
    if isinstance(path_type, models.PathTypeJointPTP):
        if not isinstance(target, models.JointPositionReference):
            raise NotImplementedYet(f"{label}: a joint PTP to a pose target is not implemented yet; use joint targets")
        return api.models.PathJointPTP(
            target_joint_position=list(target.joints.root), path_definition_name="PathJointPTP"
        )
    pose = _target_pose(label, path_type.path_definition_name, target)
    if isinstance(path_type, models.PathTypeLine):
        return api.models.PathLine(target_pose=pose, path_definition_name="PathLine")
    if isinstance(path_type, models.PathTypeCartesianPTP):
        assert isinstance(target, models.InlinePose)
        return api.models.PathCartesianPTP(
            target_pose=pose,
            kinematic_configuration=_kinematic_configuration(target),
            path_definition_name="PathCartesianPTP",
        )
    if isinstance(path_type, models.PathTypeCircle):
        via = path_type.via_pose.root
        if not isinstance(via, models.InlinePose):
            raise NotImplementedYet(f"{label}: a circle via a joint position is not implemented yet")
        return api.models.PathCircle(target_pose=pose, via_pose=_pose(via), path_definition_name="PathCircle")
    raise NotImplementedYet(f"{label}: the path type {path_type.path_definition_name} is not implemented yet")


def _target_pose(label: str, path: str, target: Any) -> api.models.Pose:
    if isinstance(target, models.JointPositionReference):
        raise NotImplementedYet(f"{label}: a {path} to a joint position target is not implemented yet")
    assert isinstance(target, models.InlinePose), "check_resolved leaves only inline poses"
    return _pose(target)


def _generated(command: models.GeneratedPathMotionCommand, limits: api.models.LimitsOverride | None) -> GeneratedMotion:
    target = command.target.root
    if isinstance(target, models.JointPositionReference):
        goal: list[float] | api.models.Pose = list(target.joints.root)
    else:
        assert isinstance(target, models.InlinePose), "check_resolved leaves only inline poses"
        goal = _pose(target)
    algorithm = command.generator.algorithm.root
    algorithm_type = (
        api.models.RRTConnectAlgorithm
        if isinstance(algorithm, models.RRTConnectAlgorithm)
        else api.models.MidpointInsertionAlgorithm
    )
    constraint = command.generator.constraint
    return GeneratedMotion(
        target=goal,
        algorithm=algorithm_type.model_validate(algorithm.model_dump(mode="json", exclude_unset=True)),
        constraint=None
        if constraint is None
        else api.models.DirectionConstraint.model_validate(constraint.model_dump(mode="json")),
        limits_override=limits,
    )


def _pose(pose: models.InlinePose) -> api.models.Pose:
    """An inline world pose (``check_resolved`` made sure of the frame; ``_tcp`` of its TCP) as the planner takes it."""
    return api.models.Pose.model_validate(pose.pose.model_dump(mode="json"))


def _kinematic_configuration(pose: models.InlinePose) -> api.models.KinematicConfiguration | None:
    configuration = pose.kinematic_configuration.root
    if not isinstance(configuration, models.SpecifiedKinematicConfiguration):
        return None
    return api.models.KinematicConfiguration.model_validate(configuration.model_dump(mode="json", exclude={"type"}))


def _settings(
    default: models.MotionSettings | None, own: models.MotionSettings | None
) -> tuple[api.models.BlendingAuto | api.models.BlendingPosition | None, api.models.LimitsOverride | None]:
    """A motion's blending and limits from the routine's defaults and its own settings (ADR 014, spec §7.2).

    - ``blending`` overrides as a whole: the motion's own if it sets one, else the routine's; ``null``
      means no blending.
    - ``limits_override`` merges field by field: each limit the motion sets wins, the others come from
      the routine's defaults; a limit set by neither is left to ``global_limits``. ``null`` skips the
      routine's defaults, so only ``global_limits`` applies.
    """
    blending: models.Blending | None = None
    limits: dict[str, Any] = {}
    for settings in (default, own):
        if settings is None:
            continue
        if "blending" in settings.model_fields_set:
            blending = settings.blending
        if "limits_override" in settings.model_fields_set:
            if settings.limits_override is None:
                limits = {}
            else:
                limits |= _set_limits(settings.limits_override)
    return _blending(blending), api.models.LimitsOverride.model_validate(limits) if limits else None


def _blending(blending: models.Blending | None) -> api.models.BlendingAuto | api.models.BlendingPosition | None:
    if blending is None:
        return None
    value = blending.root.model_dump(mode="json", exclude_none=True)
    if isinstance(blending.root, models.BlendingAuto):
        return api.models.BlendingAuto.model_validate(value)
    return api.models.BlendingPosition.model_validate(value)


def _set_limits(limits: models.LimitsOverride) -> dict[str, Any]:
    """The limits ``limits`` sets; an array field replaces as a whole list (ADR 014)."""
    value = limits.model_dump(mode="json", exclude_none=True)
    return {name: limit for name, limit in value.items() if limit != []}
"""Planning a routine's motions into one trajectory, without moving the robot.

Consecutive motions along explicit paths are planned in one ``planTrajectory`` request, so they
blend into each other. A generated (collision-free) motion is planned on its own, from where the
motions before it end, as the SDK plans collision-free motions in an action list: a pose target is
turned into joints by inverse kinematics, and ``planCollisionFree`` generates the path. A wait also
ends a piece (ADR 003/026).

The pieces are joined end to end; location ``k`` stays the start of motion ``k``.

The motion group's description on its controller decides what the routine's setup cannot: that the motion group
exists, how many joints it has, and the offset of the TCP the routine's poses were taught with. That TCP is the
ground truth (decision 26); its offset replaces the setup's ``tcp_offset``, as the SDK takes it from the
description too. A routine moved to another motion group (the request's ``motion_group_override``) is planned
with that motion group's whole setup from its description instead of the routine's.

When a motion cannot be planned, the refusal (``PlanningFailed``) names its command and carries what the planner
reports, on the routine's location scale: its feedback, where planning failed and the trajectory up to there.
"""

